          label: 'Open URL',
          description: 'Opens a URL (string) in a new tab by default. Pass in { newTab: false } to open url in current tab. Pass in { forceReload: true } to prevent client side routing and force a page reload. URL string must start with http:\/\/ or https:\/\/.',
          example: '`utils.openUrl(url, { newTab: boolean = true, forceReload: boolean = false })`',
